   llFig({x:hx-34,y:122-LL.OY,f:1,mv:0},LL.OY,'#e8e8f0','#1a1420',0,1);rect(hx-37,116,6,2,'#e03a4a');llFig({x:hx+34,y:122-LL.OY,f:-1,mv:0},LL.OY,'#3a4668','#2a2a34',3,0);rect(hx+20,104,12,2,'#3a4668');
   if(zap){c.strokeStyle='#ffe080';c.lineWidth=1;c.beginPath();c.moveTo(hx+12,hy);for(let k=0;k<5;k++)c.lineTo(hx+14+k*5,hy-4+((T*7+k*13)%9));c.stroke();txt(side==='v'?'(that was your hand)':'(that was his hand)',160,72,'#ff9a8a',9,'center')}
