    f:{lab:'The cold store',ex:()=>R.side==='v'?[['','Rations. Tinned peaches. Two smokehouse sausages that are confiscated and therefore, technically, yours.']]:[['','Rations, peaches, and two of your sausages behind a sign in his handwriting: “EVIDENCE”.']]},
    k:{lab:'The kettle',ex:()=>[['','A kettle and two mugs. One says WORLD’S OKAYEST SERGEANT. He uses it every day and has never asked where it came from.']]},
